function clip(s, max) { const t = String(s || '').replace(/\s+/g, ' ').trim(); return t.length > max ? t.slice(0, max - 1) + '…' : t; }
const SUMMARY_MAX = 200;
const NAME_MAX = 40;

const item = $input.first().json || {};
const execution = item.execution || {};
const trigger = item.trigger || {};
const workflow = item.workflow || {};
const error = execution.error || trigger.error || {};
const nowMs = Date.now();

const workflowName = workflow.name || 'workflow';
const name = clip(workflowName, NAME_MAX);
const prefix = execution.lastNodeExecuted ? execution.lastNodeExecuted + ': ' : (trigger.error ? (error.name || '') + ': ' : '');
const message = error.message || (error.cause || {}).message || '';
const summary = clip(workflowName + ' run failed: ' + prefix + message, SUMMARY_MAX);

const source = { name, status: 'failed' };
if (/^https?:\/\//.test(execution.url || '')) source.run_url = execution.url;

const envelope = { source: 'n8n', event_type: 'source_health', delivery: 'immediate', event_id: 'source-health:' + (workflow.id || 'unknown') + ':' + (execution.id || String(nowMs)), occurred_at: nowMs };
const body = JSON.stringify({ signals: [{ skill: 'yui-daily-briefing', summary, sources: [source], refs: [] }], envelope });

return [{ json: { body } }];
